+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears in its first or last name, ignoring case and accents, and when its
+ * status is one of {@code statuses}. An empty name or an empty status set
+ * matches everything.
+ *
+ * @param name     free text; may be {@code null}
+ * @param statuses statuses to show; may be {@code null} or empty for all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    /** Whether this filter matches every customer. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The folded, non-blank name terms. */
+    public List<String> nameTerms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(fold(name)))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Lower-cases text and strips its accents, so that {@code Mäkinen} becomes {@code makinen}. */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
