+
+/** Drives the running application in headless Chromium. */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerFilterBrowserIT {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    private Page open(String query) {
+        Page page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/" + query);
+        page.locator("vaadin-grid").waitFor();
+        return page;
+    }
+
+    private static Locator summary(Page page) {
+        return page.getByText("Showing ");
+    }
+
+    @Test
+    void typingFiltersWithFewQueriesAndUpdatesUrl() {
+        Page page = open("");
+        PlaywrightAssertions.assertThat(summary(page)).hasText("Showing 500 of 500");
+        page.waitForTimeout(500);
+        queryLog.clear();
+        Object historyBefore = page.evaluate("history.length");
+
+        Locator input = page.locator("vaadin-text-field input");
+        input.pressSequentially("aaltonen", new Locator.PressSequentiallyOptions().setDelay(80));
+        PlaywrightAssertions.assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/\\?name=aaltonen$"));
+        page.waitForTimeout(800);
+        String text = summary(page).textContent();
+        System.out.println("summary=" + text + " pages=" + queryLog.pageQueries()
+                + " counts=" + queryLog.countQueries() + " url=" + page.url());
+        assertTrue(queryLog.pageQueries().size() <= 2, "page queries: " + queryLog.pageQueries());
+        assertTrue(text.matches("Showing [1-9]\\d* of 500"), text);
+
+        assertEquals(historyBefore, page.evaluate("history.length"));
+
+        input.fill("");
+        PlaywrightAssertions.assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/$"));
+        PlaywrightAssertions.assertThat(summary(page)).hasText("Showing 500 of 500");
+        page.close();
+    }
+
+    @Test
+    void statusSelectionWritesUrlAndUrlIsRead() {
+        Page page = open("?name=vir&status=ACTIVE,CLOSED");
+        assertEquals("vir", page.locator("vaadin-text-field input").inputValue());
+        String text = summary(page).textContent();
+        System.out.println("from url: " + text);
+        assertTrue(!text.equals("Showing 500 of 500"));
+
+        page.navigate("http://localhost:" + port + "/");
+        page.locator("vaadin-grid").waitFor();
+        page.locator("vaadin-multi-select-combo-box input").click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(new Locator.FilterOptions().setHasText("CLOSED")).click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(new Locator.FilterOptions().setHasText("ACTIVE")).click();
+        page.keyboard().press("Escape");
+        PlaywrightAssertions.assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/\\?status=ACTIVE,CLOSED$"));
+
+        // The rewritten URL must survive a reload, and filtering must keep working after it.
+        page.reload();
+        page.locator("vaadin-grid").waitFor();
+        String closedAndActive = summary(page).textContent();
+        page.locator("vaadin-text-field input").fill("ada");
+        PlaywrightAssertions.assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/\\?name=ada&status=ACTIVE,CLOSED$"));
+        page.waitForTimeout(800);
+        System.out.println("after reload: " + closedAndActive + " / " + summary(page).textContent());
+        assertTrue(!summary(page).textContent().equals(closedAndActive));
+        page.close();
+    }
